      return null;
    }

    // Skip fixed-width injection for containers inside Bootstrap modals
    if (container.closest && container.closest('.modal')) {
      return null;
    }

    var width = calcWidth(options);
    container.style.width = width;
    container.style.maxWidth = width;
    container.style.marginLeft = 'auto';
    container.style.marginRight = 'auto';

    return width;
  }

  function calcHeight(options) {
    var cfg = mergeOptions(options);
    applyContainerWidth(cfg.container, cfg);
    var viewportHeight = getViewportHeight();
    var topOffset = getContainerTop(cfg.container);
    var availableHeight = viewportHeight - topOffset - cfg.internalChrome - cfg.bottomMargin;
    var scaleFactor = getScaleFactor();

    if (scaleFactor > 0 && scaleFactor < 1) {
      availableHeight = availableHeight / scaleFactor;
    }

    var finalHeight = Math.max(cfg.minHeight, Math.floor(availableHeight));
    return finalHeight + 'px';
  }

  function resolveDataTable(tableRef) {
    var $ = global.jQuery;
    if (!$ || !$.fn || !$.fn.DataTable) {
      return null;
    }

    if (tableRef && typeof tableRef.settings === 'function') {
      return tableRef;
    }

    if (tableRef && tableRef.jquery) {
      if (tableRef.length && $.fn.DataTable.isDataTable(tableRef.get(0))) {
        return tableRef.DataTable();
      }
      return null;
    }

    if (typeof tableRef === 'string') {
      var $table = $(tableRef);
      if ($table.length && $.fn.DataTable.isDataTable($table.get(0))) {
        return $table.DataTable();
      }
      return null;
    }

    if (tableRef && tableRef.nodeType === 1 && $.fn.DataTable.isDataTable(tableRef)) {
      return $(tableRef).DataTable();
    }

    return null;
  }

  function applyToDataTable(tableRef, options) {
    var cfg = mergeOptions(options);
    var width = applyContainerWidth(cfg.container, cfg);
    var newHeight = calcHeight(cfg);
    var api = resolveDataTable(tableRef);

    if (!api) {
      return newHeight;
    }

    var settings = api.settings && api.settings()[0];
    if (!settings) {
      return newHeight;
    }

    var scrollBody = settings.nScrollBody;
    if (scrollBody) {
      scrollBody.style.height = newHeight;
      scrollBody.style.maxHeight = newHeight;
    }

    if (settings.oScroll) {
      settings.oScroll.sY = newHeight;
    }

    if (width) {
      var wrapper = settings.nTableWrapper;
      if (wrapper) {
        wrapper.style.width = '100%';
        wrapper.style.maxWidth = '100%';
      }

      var tableNode = api.table().node();
      if (tableNode) {
        tableNode.style.width = '100%';
      }
    }

    api.columns.adjust();
    return newHeight;
  }

  global.DataTableHeightManager = {
    calcHeight: calcHeight,
    calcWidth: calcWidth,
    applyContainerWidth: applyContainerWidth,
    applyToDataTable: applyToDataTable,
    getScaleFactor: getScaleFactor,
  };
})(window);

/**
 * Mobile Table Fix - Card View Injector
 * Auto-injects data-label attributes for CSS Card View
 */
document.addEventListener('DOMContentLoaded', function () {
  initMobileTables();

  // Bind DataTables redraw event only if jQuery is available
  if (typeof $ !== 'undefined' && $.fn && $.fn.dataTable) {
    $(document).on('draw.dt', function () {
      initMobileTables();
    });
  }
});

function initMobileTables() {
  const tables = document.querySelectorAll('table:not(#hot-container table)');

  tables.forEach((table) => {
    // Find headers
    const headers = Array.from(table.querySelectorAll('thead th')).map((th) => th.innerText.trim());

    // Find rows
    const rows = table.querySelectorAll('tbody tr');

    rows.forEach((row) => {
      const cells = row.querySelectorAll('td');
      cells.forEach((cell, index) => {
        if (headers[index]) {
          cell.setAttribute('data-label', headers[index]);
        }
      });
    });
  });
  console.log('Mobile Table Fix applied: Data-labels injected.');
}

/**
 * Global Configuration for DataTables Alignment (Robust V3)
 * Uses standard DataTables API methods and modern ResizeObserver
 * to ensure alignment persists through dynamic layout changes.
 */
(function () {
  var checkInterval = 50;
  var maxAttempts = 200; // 10 seconds timeout
  var attempts = 0;

  function initFix($) {
    console.log('DataTables Alignment Fix: Initializing V3...');

    // 1. Override Defaults
    if ($.fn.dataTable.defaults) {
      $.extend(true, $.fn.dataTable.defaults, {
        autoWidth: false, // Essential for scrollY alignment
        scrollCollapse: true, // Allows table to shrink
        initComplete: function (settings, json) {
          var api = new $.fn.dataTable.Api(settings);
          // Use a small timeout to allow UI to settle
          setTimeout(function () {
            api.columns.adjust();
            attachObserver(settings);
          }, 200);
        },
      });
    }

    // Helper to attach ResizeObserver to a specific table's scroll body
    function attachObserver(settings) {
      if (!settings || !settings.nScrollBody) return;

      var scrollBody = settings.nScrollBody;
      if (window.ResizeObserver) {
        var ro = new ResizeObserver(function (entries) {
          // Start a micro-task to adjust columns
          // We check if table is still valid
          var api = new $.fn.dataTable.Api(settings);
          if (api.table().node()) {
            api.columns.adjust();
          }
        });
        ro.observe(scrollBody);
      }
    }

    // 2. Retroactive Fix for existing tables
    function retroactiveFix() {
      if ($.fn.dataTable.tables) {
        var tables = $.fn.dataTable.tables(true);
        $(tables).each(function () {
          var dt = $(this).DataTable();
          var settings = dt.settings()[0];
          if (settings) {
            try {
              if (settings.oFeatures) settings.oFeatures.bAutoWidth = false;
            } catch (e) {}

            attachObserver(settings);
            dt.columns.adjust().draw(false);
          }
        });
      }
    }

    // Bind to Window Resize (Backup)
    var resizeTimer;
    $(window).on('resize', function () {
      clearTimeout(resizeTimer);
      resizeTimer = setTimeout(function () {
        if ($.fn.dataTable.tables) {
          var tables = $.fn.dataTable.tables(true);
          $(tables).DataTable().columns.adjust();
        }
      }, 200);
    });

    // Bind to Window Load
    $(window).on('load', function () {
      retroactiveFix();
    });

    // Immediate trigger
    retroactiveFix();
  }

  function checkDeps() {
    if (document.getElementById('hot-container')) return;
    if (window.jQuery && window.jQuery.fn && window.jQuery.fn.dataTable) {
      initFix(window.jQuery);
    } else if (attempts < maxAttempts) {
      attempts++;
      setTimeout(checkDeps, checkInterval);
    } else {
      console.warn('DataTables Alignment Fix: Timed out waiting for DataTables.');
    }
  }

  checkDeps();
})();

/**
 * RBAC Capabilities Helper
 *
 * Centraliza las reglas de negocio UI basadas en los roles canónicos de la nueva arquitectura RBAC.
 * Reemplaza la lógica espagueti de `if(permiso == "P")` dispersa en las vistas legacy.
 */

const RbacCapabilities = {
  /**
   * Determina si un usuario tiene capacidad de escritura y edición total en el Last Planner System (PG, PI, PS).
   * @param {string} role - El código de rol del usuario actual (ej. 'A', 'D', 'R', 'V').
   * @param {number} currentWeek - La semana que se está visualizando.
   * @param {number} maxWeek - La semana máxima actual del proyecto (Semanas_Activas).
   * @returns {boolean}
   */
  canEditLps: function (role, currentWeek, maxWeek) {
    // Validation of data consistency
    if (!role) return false;

    // Roles con privilegios administrativos (pueden editar semanas históricas)
    if (role === 'A' || role === 'D') {
      return true;
    }

    // Roles técnicos/especialistas (solo pueden editar semanas actuales/futuras)
    // La tolerancia típica es Max_Semana - 2
    var isEditableWeek = maxWeek - 2 >= currentWeek ? false : true;

    if (isEditableWeek) {
      const allowedRoles = ['R', 'DCV'];
      return allowedRoles.includes(role);
    }

    return false;
  },

  /**
   * Determina si un usuario puede ver botones de acceso exclusivo administrativo u Oficina Técnica (ej. contratos, PDC).
   */
  canManageContracts: function (role) {
    const allowedRoles = ['A', 'D', 'OT']; // Asumiendo que Admin, Director y Oficina Técnica gestionan esto. Ajustar si R necesita.
    return allowedRoles.includes(role);
  },

  canManagePdC: function (role) {
    return this.canManageContracts(role);
  },

  canManageWeeks: function (role) {
    return ['A', 'D', 'OT', 'R', 'DCV'].includes(role);
  },

  canEditGeneralProgram: function (role) {
    return ['A', 'D', 'R', 'DCV'].includes(role);
  },

  canEditPastGeneralProgram: function (role) {
    return ['A', 'D'].includes(role);
  },

  canManageGeneralProgram: function (role) {
    return this.canEditGeneralProgram(role);
  },

  canManageMediumTermProgram: function (role) {
    return ['A', 'D', 'R', 'DCV'].includes(role);
  },

  canManageWeeklyProgram: function (role) {
    return ['A', 'D', 'R', 'S', 'G', 'SG'].includes(role);
  },

  /**
   * Determina si un rol es estrictamente de solo lectura (Visitante, Subcontratista inicial).
   */
  isReadOnly: function (role) {
    const readOnlyRoles = ['V', 'C'];
    return readOnlyRoles.includes(role);
  },

  /**
   * Traducción amigable del rol (Fallback client-side si se requiere)
   */
  getRoleName: function (role) {
    const dictionary = {
      A: 'Administrador de Sistema',
      D: 'Director de Proyecto',
      R: 'Residente de Obra',
      DCV: 'Profesional DCV',
      OT: 'Oficina Técnica',
      G: 'Residente Ambiental',
      S: 'Residente SST',
      SG: 'Residente Socio-Ambiental',
      C: 'Subcontratista',
      V: 'Visitante',
    };
    return dictionary[role] || 'Desconocido';
  },
};

function readRbacRole() {
  var el = document.getElementById('permiso_canonico');
  return String(el ? el.value : '').trim().toUpperCase();
}

function buildLegacyCapabilities() {
  var resolveRole = function () {
    return readRbacRole();
  };

  var legacyCaps = {};

  Object.defineProperties(legacyCaps, {
    canManageWeeks: {
      enumerable: true,
      get: function () {
        return RbacCapabilities.canManageWeeks(resolveRole());
      },
    },
    canEditGeneralProgram: {
      enumerable: true,
      get: function () {
        return RbacCapabilities.canEditGeneralProgram(resolveRole());
      },
    },
    canManageGeneralProgram: {
      enumerable: true,
      get: function () {
        return RbacCapabilities.canManageGeneralProgram(resolveRole());
      },
    },
    canEditPastGeneralProgram: {
      enumerable: true,
      get: function () {
        return RbacCapabilities.canEditPastGeneralProgram(resolveRole());
      },
    },
    canManageMediumTermProgram: {
      enumerable: true,
      get: function () {
        return RbacCapabilities.canManageMediumTermProgram(resolveRole());
      },
    },
    canManageWeeklyProgram: {
      enumerable: true,
      get: function () {
        return RbacCapabilities.canManageWeeklyProgram(resolveRole());
      },
    },
    canManageContracts: {
      enumerable: true,
      get: function () {
        return RbacCapabilities.canManageContracts(resolveRole());
      },
    },
    canManagePdC: {
      enumerable: true,
      get: function () {
        return RbacCapabilities.canManagePdC(resolveRole());
      },
    },
    isReadOnly: {
      enumerable: true,
      get: function () {
        return RbacCapabilities.isReadOnly(resolveRole());
      },
    },
  });

  return legacyCaps;
}

// Exponer globalmente para las vistas legacy
window.RbacCapabilities = RbacCapabilities;
window.rbacCapabilities = buildLegacyCapabilities();

(function() {
    function handleSessionExpiry(payload) {
        var redirectUrl = (payload && payload.redirect) || '/logout?timeout=1';

        if (window.AIA && window.AIA.SessionTimeoutManager && typeof window.AIA.SessionTimeoutManager.forceLogout === 'function') {
            window.AIA.SessionTimeoutManager.forceLogout(redirectUrl);
            return;
        }

        window.location.replace(redirectUrl);
    }

    function initNotifications() {
    const badgeDesk = document.getElementById('notificationBadge');
    const listDesk = document.getElementById('notificationList');
    const badgeMob = document.getElementById('notificationBadgeMobile');
    const listMob = document.getElementById('notificationListMobile');

    if (!badgeDesk && !badgeMob) return;

    // Obtener notificaciones
    function fetchNotifications() {
        fetch('/api/notifications/unread', {
            headers: {
                'X-AIA-Expect-Json': '1',
                'X-AIA-Idle-Refresh': '0',
                'X-Requested-With': 'XMLHttpRequest'
            }
        })
            .then(response => {
                if (response.status === 401) {
                    return response.json()
                        .then(payload => {
                            handleSessionExpiry(payload);
                            return null;
                        })
                        .catch(() => {
                            handleSessionExpiry();
                            return null;
                        });
                }

                if (!response.ok) throw new Error('Network response was not ok');
                return response.json();
            })
            .then(res => {
                if (!res) {
                    return;
                }

                if (res.success && res.data) {
                    renderNotifications(res.data);
                }
            })
            .catch(err => console.error('Error fetching notifications:', err));
    }

    // Dibujar en el DOM
    function renderNotifications(data) {
        if (data.length > 0) {
            if (badgeDesk) {
                badgeDesk.textContent = data.length;
                badgeDesk.style.display = 'inline-block';
            }
            if (badgeMob) {
                badgeMob.textContent = data.length;
                badgeMob.style.display = 'inline-block';
            }

            let html = '';
            data.forEach(item => {
                // Formato de fecha simple
                const date = new Date(item.created_at).toLocaleDateString('es-CO', {day: '2-digit', month: 'short'});
                const count = parseInt(item.item_count) || 1;
                const countBadge = count > 1 ? `<span class="badge badge-pill badge-secondary ml-1" style="font-size:0.65rem;">${count}</span>` : '';

                html += `
                <a class="dropdown-item d-flex align-items-center border-bottom py-2 notification-item" href="#" data-id="${item.id}" style="white-space: normal;">
                    <div class="mr-3">
                        <div class="icon-circle bg-warning text-white" style="width: 30px; height: 30px; border-radius: 50%; display: flex; align-items: center; justify-content: center;">
                            <i class="fas fa-exclamation-triangle text-xs"></i>
                        </div>
                    </div>
                    <div>
                        <div class="small text-gray-500">${date}</div>
                        <span class="font-weight-bold" style="font-size: 0.85rem;">${item.title}${countBadge}</span>
                        <div class="small text-muted" style="font-size: 0.75rem; line-height: 1.2;">${item.message}</div>
                    </div>
                </a>`;
            });
            if (listDesk) listDesk.innerHTML = html;
            if (listMob) listMob.innerHTML = html;

            // Asignar eventos de "Marcar como leído"
            document.querySelectorAll('.notification-item').forEach(el => {
                el.addEventListener('click', function(e) {
                    e.preventDefault();
                    e.stopPropagation();
                    const notifId = this.getAttribute('data-id');
                    // Find all matching notifications in both lists
                    const allMatching = document.querySelectorAll(`.notification-item[data-id="${notifId}"]`);
                    markAsRead(notifId, Array.from(allMatching));
                });
            });

        } else {
            const emptyHtml = '<a class="dropdown-item text-muted text-center py-3" href="#">No hay notificaciones nuevas</a>';
            if (badgeDesk) { badgeDesk.style.display = 'none'; }
            if (badgeMob) { badgeMob.style.display = 'none'; }
            if (listDesk) { listDesk.innerHTML = emptyHtml; }
            if (listMob) { listMob.innerHTML = emptyHtml; }
        }
    }

    // Marcar como leído
    function markAsRead(id, elementNodes) {
        fetch('/api/notifications/read', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({ id: id })
        })
        .then(response => response.json())
        .then(res => {
            if (res.success) {
                // Remover visualmente de todas las listas
                elementNodes.forEach(node => node.remove());

                // Read current count
                let currentText = badgeDesk ? badgeDesk.textContent : (badgeMob ? badgeMob.textContent : "0");
                let currentCount = parseInt(currentText) || 0;
                currentCount--;

                if (currentCount > 0) {
                    if (badgeDesk) badgeDesk.textContent = currentCount;
                    if (badgeMob) badgeMob.textContent = currentCount;
                } else {
                    const emptyHtml = '<a class="dropdown-item text-muted text-center py-3" href="#">No hay notificaciones nuevas</a>';
                    if (badgeDesk) { badgeDesk.style.display = 'none'; listDesk.innerHTML = emptyHtml; }
                    if (badgeMob) { badgeMob.style.display = 'none'; listMob.innerHTML = emptyHtml; }
                }
            }
        });
    }

    // Llamada inicial
    fetchNotifications();

    // Polling ligero (cada 120 segundos)
    setInterval(fetchNotifications, 120000);
    } // fin initNotifications

    // Ejecutar: si el DOM ya cargó, ejecutar directo; si no, esperar
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initNotifications);
    } else {
        // DOM ya listo (carga dinámica vía createElement)
        initNotifications();
    }
})();

/**
 * Context Manager
 * Handles global application state (Week, Project, Module)
 * Dispatches events when context changes.
 */
class ContextManager {
  constructor() {
    this.state = {
      project: '',
      week: 0,
      module: '',
    };
    this.init();
  }

  init() {
    // Read initial state from hidden inputs if available (Legacy Support)
    const weekInput = document.getElementById('semana');
    const projectInput = document.getElementById('proyecto');

    if (weekInput) this.state.week = parseInt(weekInput.value) || 0;
    if (projectInput) this.state.project = projectInput.value || '';

    // Listen for internal events
    document.addEventListener('context:change_week', (e) =>
      this.setWeek(e.detail.week, e.detail.redirect)
    );
  }

  async setWeek(week, redirectUrl = null) {
    if (!week) return;

    try {
      const response = await fetch('/context/week', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ semana: week }),
      });
      const data = await response.json();

      if (data.success) {
        this.state.week = week;
        // Dispatch updated event
        document.dispatchEvent(new CustomEvent('context:updated', { detail: this.state }));

        if (redirectUrl) {
          window.location.href = redirectUrl;
        } else {
          window.location.reload();
        }
      } else {
        console.error('Context Error:', data.message);
        if (window.AIA && window.AIA.Notice && typeof window.AIA.Notice.error === 'function') {
          AIA.Notice.error('No se pudo cambiar la semana: ' + data.message);
        } else if (typeof window.alert === 'function') {
          window.alert('No se pudo cambiar la semana: ' + data.message);
        }
      }
    } catch (err) {
      console.error('Network Error:', err);
    }
  }

  async clearWeek(redirectUrl = null) {
    try {
      const response = await fetch('/context/clear-week', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
      });
      const data = await response.json();

      if (data.success) {
        this.state.week = 0;
        // Dispatch updated event
        document.dispatchEvent(new CustomEvent('context:updated', { detail: this.state }));

        if (redirectUrl) {
          window.location.href = redirectUrl;
        } else {
          window.location.reload();
        }
      }
    } catch (err) {
      console.error('Network Error:', err);
    }
  }
}

// Initialize Global Context
window.Context = new ContextManager();

// Global Helper for Legacy Onclicks
window.cambiarSemanaSesion = (week, url) => {
  window.Context.setWeek(week, url);
};
